import { adapterOas } from "@kubb/adapter-oas";
import { pluginFetch } from "@kubb/plugin-fetch";
import { pluginMsw } from "@kubb/plugin-msw";
import { pluginReactQuery } from "@kubb/plugin-react-query";
import { pluginTs } from "@kubb/plugin-ts";
import { pluginZod } from "@kubb/plugin-zod";
import { defineConfig } from "kubb";

/**
 * Generates the typed API client from the backend's OpenAPI document (ADR 0007).
 * `web/openapi/app.json` is regenerated by `dotnet build src/App.Api`; then run `pnpm api:generate`.
 * Output is committed and must never be edited by hand.
 */
export default defineConfig({
  name: "app-api",
  // The API emits OpenAPI 3.1 (ADR 0007), which Kubb's bundled OpenAPI validator supports.
  adapter: adapterOas({ validate: true }),
  input: "./openapi/app.json",
  output: {
    path: "./src/lib/api/gen",
    clean: true,
    // Formatted by a separate oxfmt step in `api:generate`: kubb's in-process format hook races its own writes on
    // Windows (os error 1224, file has a user-mapped section open).
    format: false,
  },
  plugins: [
    pluginTs({ output: { path: "types" } }),
    pluginZod({ output: { path: "zod" } }),
    // Same-origin requests: the API serves the SPA (and Vite proxies /api in dev), so no base URL.
    pluginFetch({ output: { path: "clients" }, returnType: "data" }),
    pluginReactQuery({ output: { path: "queries" } }),
    pluginMsw({ output: { path: "msw" } }),
  ],
});
